def get_reservation_flight_times(reservation_id: str):
    """
    Get the scheduled departure/arrival times and DURATIONS of every flight in a reservation, plus
    the layover time between connecting flights and the total duration of each journey (outbound,
    and return for a round trip) including layovers. Use this whenever the user asks how long the
    flights are, or wants to act on flights longer/shorter than some number of hours.
    get_reservation_details does NOT contain times; this tool looks them up for you.

    All times are EST. A time ending in "+1" is on the next day.

    HOW TO APPLY A DURATION CONDITION ("cancel trips with a flight longer than 4 hours", "upgrade the
    ones with flights of 3 hours or less, including layovers"):
    1. Compare EACH FLIGHT's duration_hours with the limit. Use "longest_flight_hours_overall".
    2. A layover is ground time between two flights, NOT part of any flight; never add it to a flight.
       "Including layovers" / "including connections" means reservations WITH connecting flights are
       considered too; each of their flights is still compared on its own.
    3. Worked example: legs of 3.0 h and 2.0 h with a 2.0 h layover -> longest_flight_hours_overall = 3.0
       -> it is NOT "longer than 4 hours" and it IS "3 hours or less".
    4. If "any_flight_flown" is true, the reservation cannot be changed, upgraded or cancelled by you.
    5. "cabin_upgrade" tells you whether the cabin can be upgraded: basic economy CAN be upgraded
       (same flights, new cabin); quote it with calculate_flight_change_cost.
    Never use these results' flight numbers for anything except this reservation; for a cabin upgrade
    keep the reservation's own flights.

    Example: get_reservation_flight_times(reservation_id="ZFA04Y") ->
        {"journeys": [{"direction": "outbound", "flights": [{"flight_number": "<flight in that reservation>", "duration_hours": 2.5, ...}],
          "total_duration_hours_including_layovers": 2.5, "longest_flight_hours": 2.5}], ...}

    Args:
        reservation_id: The reservation ID, such as 'ZFA04Y'.

    Returns:
        A dict with one entry per journey; each lists its flights (departure, arrival, duration_hours),
        layover_hours between flights, total_duration_hours_including_layovers and longest_flight_hours.
    """
    res = env_get_reservation_details(reservation_id=reservation_id)
    if not isinstance(res, dict):
        return res

    def _mins(t):
        # "HH:MM:SS" or "HH:MM:SS+1" -> minutes from midnight of the flight date
        extra = 0
        t = str(t)
        if "+" in t:
            t, plus = t.split("+", 1)
            try:
                extra = int(plus) * 24 * 60
            except ValueError:
                extra = 24 * 60
        h, m = t.split(":")[0:2]
        return int(h) * 60 + int(m) + extra

    def _day(date):
        y, m, d = date.split("-")
        return int(d) + 31 * int(m) + 372 * int(y)

    def _schedule(f):
        # scheduled times are the same for a flight number on every date; search the flight's date first
        y, m, d = f["date"].split("-")
        dates = [f["date"]]
        for k in range(1, 31):
            for dd in (int(d) + k, int(d) - k):
                if 1 <= dd <= 31:
                    dates.append("%s-%s-%02d" % (y, m, dd))
        for date in dates:
            r = env_search_direct_flight(origin=f["origin"], destination=f["destination"], date=date)
            if isinstance(r, list):
                for x in r:
                    if x.get("flight_number") == f["flight_number"]:
                        return x.get("scheduled_departure_time_est"), x.get("scheduled_arrival_time_est")
        return None, None

    legs = []
    for f in res.get("flights") or []:
        dep, arr = _schedule(f)
        st = env_get_flight_status(flight_number=f["flight_number"], date=f["date"])
        leg = {"flight_number": f["flight_number"], "origin": f["origin"], "destination": f["destination"],
               "date": f["date"], "status": st if isinstance(st, str) else None,
               "departure_est": dep, "arrival_est": arr}
        if dep and arr:
            leg["duration_hours"] = round((_mins(arr) - _mins(dep)) / 60.0, 2)
            leg["_start"] = _day(f["date"]) * 1440 + _mins(dep)
            leg["_end"] = _day(f["date"]) * 1440 + _mins(arr)
        else:
            leg["duration_hours"] = None
            leg["note"] = "schedule not found"
        legs.append(leg)

    # split into journeys: outbound ends at the reservation destination
    journeys = []
    if res.get("flight_type") == "round_trip":
        cut = None
        for i, leg in enumerate(legs):
            if leg["destination"] == res.get("destination"):
                cut = i + 1
                break
        if cut is None:
            journeys = [("outbound", legs)]
        else:
            journeys = [("outbound", legs[:cut]), ("return", legs[cut:])]
    else:
        journeys = [("outbound", legs)]

    out = []
    for name, js in journeys:
        if not js:
            continue
        layovers = []
        for a, b in zip(js, js[1:]):
            if "_end" in a and "_start" in b:
                layovers.append({"at": a["destination"], "layover_hours": round((b["_start"] - a["_end"]) / 60.0, 2)})
            else:
                layovers.append({"at": a["destination"], "layover_hours": None})
        total = None
        if all("_start" in x for x in js):
            total = round((js[-1]["_end"] - js[0]["_start"]) / 60.0, 2)
        durs = [x["duration_hours"] for x in js if x["duration_hours"] is not None]
        out.append({
            "direction": name,
            "flights": [{k: v for k, v in x.items() if not k.startswith("_")} for x in js],
            "layovers": layovers,
            "total_duration_hours_including_layovers": total,
            "longest_flight_hours": max(durs) if durs else None,
        })

    all_durs = [x["duration_hours"] for x in legs if x["duration_hours"] is not None]
    flown = any(x.get("status") in ("landed", "flying") for x in legs)
    if res.get("status") == "cancelled":
        upgrade = "no: the reservation is cancelled"
    elif flown:
        upgrade = "no: a flight was already flown"
    elif res.get("cabin") == "business":
        upgrade = "already business"
    else:
        upgrade = ("yes: " + str(res.get("cabin")) + " can be upgraded to a higher cabin with the same flights "
                   "(quote it with calculate_flight_change_cost first)")
    return {"reservation_id": reservation_id, "flight_type": res.get("flight_type"), "cabin": res.get("cabin"),
            "status": res.get("status"), "journeys": out,
            "all_flight_durations_hours": all_durs,
            "longest_flight_hours_overall": max(all_durs) if all_durs else None,
            "any_flight_flown": flown,
            "cabin_upgrade": upgrade}
